mapper.insert:

            /* isry.csemd.casemng.mapper.CsemdCaseMngMapper.insertAFA410 - 개발지원팀 이승연  */
            INSERT INTO AFA410
            (
               CASE_MNG_NO       /* 사례관리번호 */
			 , CASE_MNG_ODRNO    /* 사례관리차수 */
			 , RQST_CN           /* 의뢰내용 */
			 , RQST_GOAL_CN      /* 의뢰목표내용 */
			 , FAM_MATTER_CN     /* 가족사항내용 */
			 , TRL_INSP_CN       /* 심리검사내용 */
			 , PRTCLR_MATTER_CN  /* 특이사항내용 */
			 , APRV_YN           /* 승인여부 */
			 , APRV_YMD          /* 승인일자 */
			 , APRV_PIC_NO       /* 승인담당자번호 */
			 , APRV_INST_NO      /* 승인기관번호 */
			 , PIC_NO            /* 담당자 번호 */
			 , FRST_RGTR_ID      /* 최초등록자아이디 */
			 , FRST_REG_DT       /* 최초등록일시 */
			 , LAST_MDFR_ID      /* 최종수정자아이디 */
			 , LAST_MDFCN_DT     /* 최종수정일시 */
            )
            VALUES
            (
               #{CASE_MNG_NO}
			 , #{CASE_MNG_ODRNO}
			 , #{RQST_CN}
			 , #{RQST_GOAL_CN}
			 , #{FAM_MATTER_CN}
			 , #{TRL_INSP_CN}
			 , #{PRTCLR_MATTER_CN}
			 , NVL(#{APRV_YN},'N')
			 , #{APRV_YMD}
			 , #{APRV_PIC_NO}
			 , #{APRV_INST_NO}
			 , #{PIC_NO}
			 , #{USER_ID}
			 , SYSDATE
			 , #{USER_ID}
			 , SYSDATE
            )

mapper.update:

/* isry.csemd.casemng.mapper.CsemdCaseMngMapper.updateAFA410 - 개발지원팀 이승연  */
UPDATE AFA410
   SET RQST_CN          = #{RQST_CN}
     , RQST_GOAL_CN     = #{RQST_GOAL_CN}
     , FAM_MATTER_CN    = #{FAM_MATTER_CN}
     , TRL_INSP_CN      = #{TRL_INSP_CN}
     , PRTCLR_MATTER_CN = #{PRTCLR_MATTER_CN}
     , APRV_YN          = #{APRV_YN}
     , APRV_YMD         = #{APRV_YMD}
     , APRV_PIC_NO      = #{APRV_PIC_NO}
     , APRV_INST_NO     = #{APRV_INST_NO}  
     , PIC_NO           = #{PIC_NO}               
     , LAST_MDFR_ID     = #{USER_ID}
     , LAST_MDFCN_DT    = SYSDATE
 WHERE CASE_MNG_NO      = #{CASE_MNG_NO}   
   AND CASE_MNG_ODRNO   = #{CASE_MNG_ODRNO}


/* isry.csemd.casemng.mapper.CsemdCaseMngMapper.updateSBB600 - 응용3팀 이상훈  */
UPDATE SBB600 SET
    CASE_MNG_NO = #{CASE_MNG_NO}
,   CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
,   LAST_MDFR_ID = #{LAST_MDFR_ID}
,   LAST_MDFCN_DT = SYSDATE
WHERE 1=1
AND INST_NO = #{INST_NO}
AND REG_YMD = #{REG_YMD}
AND MNG_SN = #{MNG_SN}
